import { describe, it, expect } from "vitest";
import { runClaimOffice } from "./cli.js";

function run(scenario: object): { results: unknown[] } {
  return runClaimOffice(JSON.stringify(scenario));
}

describe("claim-office", () => {
  it.todo("should return 5 G premium for an empty item list (only processing fee)");

  it.todo("should return 50 G base premium for 2 runes");

  it.todo("should return 60 G base premium for 3 runes (block applies)");

  it.todo("should return 100 G base premium for 4 runes (no block, block requires exactly 3)");

  it.todo("should return 175 G base premium for 7 runes");

  it.todo("should return 75 G base premium for 2 runes + 1 moonstone (no block, different types)");

  it.todo("should return 120 G base premium for 3 runes + 3 moonstones (two separate blocks)");

  it.todo("should apply item-specific cursed surcharge only to the cursed item's base premium (cursed sword + plain amulet -> 210 G before fee)");

  it.todo("should apply loyalty discount when customer has exactly 2 years with MHPCO");

  it.todo("should apply high-enchantment surcharge for a sword with exactly enchantment 5");

  it.todo("should apply both curse and high-enchantment surcharges for a cursed sword at enchantment 5");

  it.todo("should not apply high-enchantment surcharge for a sword with enchantment 4");

  it.todo("should process newcomer cursed sword premium as 165 G");

  it.todo("should process long-standing customer second contract cursed sword premium as 160 G");

  it.todo("should round premium 197.5 G up to 198 G");

  it.todo("should process standard reimbursement for steel sword enchantment 3, damage 500 G -> 400 G payout");

  it.todo("should process rune damage 200 G -> 100 G payout");

  it.todo("should reimburse high-enchantment (>= 8) damage at 50%: dragon sword enchant 8, damage 1000 G -> 400 G payout");

  it.todo("should fully reimburse dragon material: dragon sword enchant 5, damage 800 G -> 700 G payout");

  it.todo("should apply 50% rule over dragon material when both apply: dragon sword enchant 9, damage 1000 G -> 400 G payout");

  it.todo("should process multiple items of same type with separate deductibles: sword 500 + amulet 300 -> 600 G payout");

  it.todo("should cap payout at remaining cap across successive claims");

  it.todo("should round payout 350.5 G down to 350 G");

  it.todo("should exit non-zero for unknown item type in quote and write error to stderr");

  it.todo("should exit non-zero when damage references an item not in policy");

  it.todo("should exit non-zero when damage amount is negative");

  it.todo("should return remainingCap = 2x insurance sum after quote for multi-item policy");
});

