export function runClaimOffice(input: string): { results: unknown[] } {
  const scenario = JSON.parse(input);
  const step = scenario.steps[0];
  const items = step.items;
  if (items.length === 0) {
    return { results: [{ premium: 5 }] };
  }
  const base = items.length * 25;
  const firstInsurance = base * 0.1;
  return { results: [{ premium: Math.round(base + firstInsurance + 5) }] };
}

