export function runClaimOffice(input: string): { results: unknown[] } {
  const scenario = JSON.parse(input);
  const step = scenario.steps[0];
  const items = step.items;
  if (items.length === 0) {
    return { results: [{ premium: 5 }] };
  }
  const base = basePremium(items);
  const firstInsurance = base * 0.1;
  return { results: [{ premium: Math.round(base + firstInsurance + 5) }] };
}

const MAIN_BASE: Record<string, number> = { sword: 100, amulet: 60, staff: 80, potion: 40 };

function basePremium(items: { type: string; cursed?: boolean }[]): number {
  const counts = new Map<string, number>();
  for (const item of items) {
    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
  }
  let total = 0;
  for (const item of items) {
    total += itemPremium(item);
  }
  return total;
}

function itemPremium(item: { type: string; cursed?: boolean }): number {
  const base = MAIN_BASE[item.type] ?? 25;
  const cursed = item.cursed ? base * 0.5 : 0;
  return base + cursed;
}

